"use client";
import { useState } from "react";
const tabs=["Daily","Monthly","Yearly"];
export default function ReportPage(){const [tab,setTab]=useState("Daily");return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-7xl"><h1 className="text-2xl font-semibold">Reports</h1><div className="mt-6 flex gap-2 border-b border-white/10">{tabs.map(t=><button key={t} onClick={()=>setTab(t)} className={`px-4 py-3 text-sm ${tab===t?"border-b-2 border-orange-500 text-orange-400":"text-white/45"}`}>{t}</button>)}</div><div className="mt-6 flex justify-end"><input type={tab==="Daily"?"date":"month"} className="field max-w-xs"/></div><div className="mt-5 grid gap-4 md:grid-cols-3">{[["TOTAL SALES","₦0"],["TOTAL PROFIT","₦0"],["TRANSACTIONS","0"]].map(([a,b])=><div key={a} className="rounded-2xl border border-white/10 bg-[#151515] p-5"><p className="text-xs text-white/40">{a}</p><p className="mt-2 text-2xl font-semibold">{b}</p></div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-2"><Section title="Payment Breakdown"><Placeholder text="Cash ₦0 · POS ₦0 · Transfer ₦0"/></Section><Section title="Top Items"><Table headers={["ITEM","QTY SOLD","REVENUE"]}/></Section><Section title="Employee Performance"><Table headers={["NAME","TRANSACTIONS","TOTAL SALES"]}/></Section><Section title="Last 7 Days — Sales Trend"><div className="flex h-48 items-end gap-3 rounded-xl bg-[#101010] p-5">{[20,55,35,75,45,90,65].map((h,i)=><div key={i} className="flex-1 rounded-t bg-orange-500/80" style={{height:`${h}%`}}/>)}</div></Section></div>{tab==="Yearly"&&<Section title="Monthly Breakdown" className="mt-5"><Table headers={["MONTH","SALES","PROFIT","TRANSACTIONS"]}/></Section>}</div></main>}
function Section({title,children,className=""}:{title:string;children:React.ReactNode;className?:string}){return <section className={`rounded-2xl border border-white/10 bg-[#151515] p-5 ${className}`}><h2 className="mb-4 font-semibold">{title}</h2>{children}</section>}
function Placeholder({text}:{text:string}){return <div className="rounded-xl border border-dashed border-white/10 p-8 text-center text-sm text-white/35">{text}</div>}
function Table({headers}:{headers:string[]}){return <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="text-xs text-white/40"><tr>{headers.map(h=><th key={h} className="px-3 py-3">{h}</th>)}</tr></thead><tbody><tr><td colSpan={headers.length} className="px-3 py-8 text-center text-white/30">No data yet</td></tr></tbody></table></div>}
